import{z as l,x as d,o as n,c as A,q as o,j as s,D as r,d as e,s as E,S as c,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"容器运行时","description":"","frontmatter":{"title":"容器运行时","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-container-runtime.md","filePath":"cs/virt-container-runtime.md","lastUpdated":1791413859000}'),B={name:"cs/virt-container-runtime.md"};function u(m,a,p,h,C,D){const i=d("Mermaid");return n(),A("div",null,[a[2]||(a[2]=o('<h1 id="容器运行时" tabindex="-1">容器运行时 <a class="header-anchor" href="#容器运行时" aria-label="Permalink to &quot;容器运行时&quot;">​</a></h1><div class="epigraph"><p>运行时不产生隔离，它只把隔离的配置写进内核再让位；谁守住容器进程的父职，谁就决定了守护进程重启时容器死不死。</p><footer>—— 据 OCI Runtime Specification 与 containerd 设计文档整理</footer></div><p><a href="/cs/virt-kvm-qemu">上一课</a>把虚拟机的控制面拆成内核陷入与用户态设备模型，接缝按退出频次挪动。容器没有陷入可挪，却有同样的问题要回答：谁应用配置、谁看住进程、谁在守护进程升级时接住孩子。主干课<a href="/cs/container-runtime">runc 与 containerd</a>给过三层轮廓；本课深钻生命周期本身：创建的两阶段、父子关系的归属，以及让隔离后端可以整体替换的那份契约。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OCI 规范把输入钉成 <strong>bundle</strong>：一个 rootfs 目录加一份 <code>config.json</code>——挂载表、命名空间集合、capabilities、cgroup 路径都在这份 JSON 里。从镜像到 bundle 是镜像规范的事：把分层快照解到 overlay 上（<a href="/cs/oci-image-layers">OCI 镜像层</a>）；从 bundle 到进程才是运行时的事。缺口在运行时内部：runc 被拆成 <code>create</code> 与 <code>start</code> 两个阶段——<code>create</code> 里 clone 出带全套命名空间的容器 init 进程，但让它停在设置好环境的第一个系统调用上等信号；运行时把容器 pid 写进文件、自己退出；<code>start</code> 只负责发信号放行。缺口是：<strong>runc 为什么必须退出，退出后父职给谁</strong>。</p><p><span class="marginnote">bundle 可以翻译成「一个目录加一份清单」：rootfs 是被隔离的那个文件系统视图，config.json 是写给内核的需求单——挂载哪些目录、关进哪些命名空间、给多少预算，运行时只是照单执行的人，清单里没有任何一行需要它自己发明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把生命周期当合同读：每一步谁持有进程、谁交接状态、谁在对面等。</p><h3 id="shim-的父职" tabindex="-1">shim 的父职 <a class="header-anchor" href="#shim-的父职" aria-label="Permalink to &quot;shim 的父职&quot;">​</a></h3><p>若让守护进程（containerd）直接当容器进程的父亲，升级或重启守护进程就得杀掉全部容器——父进程死，孤儿被收养，监控与 reap 全乱。shim 因此存在：runc 先于 shim 启动容器，再把父职让给常驻的 shim 进程；容器 init 退出时 SIGCHLD 落在 shim 上，状态由 shim 上报。守护进程随便重启，容器进程树原封不动。runc 在 <code>start</code> 完成后消失，它的历史使命只有「以正确参数写内核」这一件事——不持有 fd、不持有管道、不留下自己的任何状态在容器侧。</p>',10)),(n(),s(c,null,{default:r(()=>[E(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTORD%5B%22containerd%20%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20SHIM%5B%22shim%20%E5%B8%B8%E9%A9%BB%3A%20%E7%88%B6%E8%81%8C%E4%B8%8E%20stdio%22%5D%0A%20%20CTORD%20--%3E%20RUNC%5B%22runc%3A%20%E8%AF%BB%20bundle%22%5D%0A%20%20RUNC%20--%3E%20CREATE%5B%22create%3A%20clone%20%E5%81%9C%E5%9C%A8%E7%AC%AC%E4%B8%80%E4%B8%AA%E8%B0%83%E7%94%A8%22%5D%0A%20%20CREATE%20--%3E%20EXITR%5B%22runc%20%E9%80%80%E5%87%BA%2C%20%E4%BA%A4%E5%87%BA%20pid%22%5D%0A%20%20CTORD%20--%3E%20START%5B%22start%3A%20%E6%94%BE%E8%A1%8C%20init%22%5D%0A%20%20START%20--%3E%20PID1%5B%22%E5%AE%B9%E5%99%A8%20init%20%E7%9C%9F%E6%AD%A3%E6%89%A7%E8%A1%8C%22%5D%0A%20%20PID1%20--%3E%20REAP%5B%22%E9%80%80%E5%87%BA%E6%97%B6%20SIGCHLD%20%E5%BD%92%20shim%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("这份契约的真正价值是"),t("strong",null,"隔离后端可替换"),e("："),t("code",null,"config.json"),e(" 描述的是「我要什么隔离视图与预算」，不描述谁来实现。同一个 bundle，runc 用 clone 进命名空间，runsc（gVisor）交给用户态内核截系统调用，Kata 起一台微虚机再在虚机里跑同样的配置。对比上一课的 KVM/QEMU：那边挪的是数据面后端，这边换的是整个隔离后端，而上游调用方（containerd、CRI）无须改一行。运行时层的正确姿势由此清晰："),t("strong",null,"它是配置的应用者与进程的监护人，不是边界本身"),e("——边界永远是内核（或替代内核）加你写进 JSON 的参数。")],-1)),(n(),s(c,null,{default:r(()=>[E(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUNDLE2%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%20bundle%22%5D%20--%3E%20RUN%5B%22runc%3A%20clone%20%E8%BF%9B%E5%91%BD%E5%90%8D%E7%A9%BA%E9%97%B4%22%5D%0A%20%20BUNDLE2%20--%3E%20GVISOR%5B%22runsc%3A%20%E7%94%A8%E6%88%B7%E6%80%81%E5%86%85%E6%A0%B8%E6%88%AA%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A%20%20BUNDLE2%20--%3E%20KATA%5B%22Kata%3A%20%E8%B5%B7%E5%BE%AE%E8%99%9A%E6%9C%BA%E5%86%8D%E5%A5%97%E5%90%8C%E4%B8%80%E9%85%8D%E7%BD%AE%22%5D%0A%20%20RUN%20--%3E%20KO%5B%22%E5%86%85%E6%A0%B8%E5%8D%B3%E8%BE%B9%E7%95%8C%22%5D%0A%20%20GVISOR%20--%3E%20SK%5B%22Sentry%20%E5%8D%B3%E8%BE%B9%E7%95%8C%22%5D%0A%20%20KATA%20--%3E%20KV%5B%22%E8%99%9A%E6%9C%BA%E5%8D%B3%E8%BE%B9%E7%95%8C%22%5D%0A%20%20KO%20--%3E%20CALLER%5B%22%E4%B8%8A%E6%B8%B8%20containerd%20%E4%B8%8E%20CRI%20%E6%97%A0%E6%84%9F%22%5D%0A%20%20SK%20--%3E%20CALLER%0A%20%20KV%20--%3E%20CALLER%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">两阶段 create/start 不是仪式：容器 init 停在第一条指令上等放行，是给运行时留的窗口——所有权管道、console、cgroup 都在进程「已存在但未运行」的状态里交接，避免了「先 exec 再补配置」永远补不齐的竞态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开镜像分层的哈希链与分发协议，也不写 Kubernetes 的 CRI 报文；hook（prestart、poststop 一类生命周期钩子）只承认存在。shim 解决的是<strong>守护进程</strong>的存活问题，不解决内核存活问题：内核升级仍要清空容器，那是<a href="/cs/live-migration">热迁移</a>与微虚机路线的动机。另一个易错点：shim 常驻不等于重——它只等一个孩子、转发三路 stdio；把「每个容器一个 shim」误当成每容器多一个重守护进程，会得出错误的密度估算。</p><p><span class="marginnote">估算密度时的量级参考：一个 shim 大致等于「一个阻塞在 waitpid 上的进程加三路转发的 stdio」，它不轮询、不主动占 CPU 时间片，常驻内存以几百 KB 计；把每容器一个 shim 乘成「重负载」，是容量规划里最常见的重复计费。</span></p><p>安全角度的边界留给<a href="/cs/virt-security-boundary">安全边界</a>一课：本课只钉「运行时不是边界」，至于 runc 自身的漏洞窗口（历史上真实出现过）如何被微虚机路线吸收，后课再收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OCI 把输入钉成 bundle：rootfs 加 config.json，运行时只是这份配置的应用者。</li><li>runc 两阶段 create/start：init 停在第一条指令上，交接完成再放行。</li><li>shim 接走父职与 stdio，守护进程升级不再连坐容器。</li><li>同一 bundle 可换隔离后端：runc、gVisor、Kata，上游调用方无感。</li><li>出处：据 OCI Runtime Specification、containerd 与 runc 设计文档整理。</li></ul>',7))])}const T=l(B,[["render",u]]);export{b as __pageData,T as default};
